import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.Crpw6aS5.js";const k=JSON.parse('{"title":"WhatsApp 接入","description":"","frontmatter":{},"headers":[],"relativePath":"im/whatsapp.md","filePath":"im/whatsapp.md","lastUpdated":1781208146000}'),p={name:"im/whatsapp.md"};function l(h,a,n,o,d,r){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="whatsapp-接入" tabindex="-1">WhatsApp 接入 <a class="header-anchor" href="#whatsapp-接入" aria-label="Permalink to &quot;WhatsApp 接入&quot;">​</a></h1><blockquote><p>WhatsApp Adapter 使用 WhatsApp Web linked device 方式接入个人号。实现基于 <code>@whiskeysockets/baileys</code>。</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>WhatsApp 方案适合用自己的 WhatsApp 个人号在私聊里远程驱动 EchoFlow Code。当前实现只处理个人私聊，不处理群聊、频道、状态广播。</p><p>实现入口：<code>adapters/whatsapp/index.ts</code></p><h2 id="它不是创建机器人" tabindex="-1">它不是“创建机器人” <a class="header-anchor" href="#它不是创建机器人" aria-label="Permalink to &quot;它不是“创建机器人”&quot;">​</a></h2><p>当前实现走的是 WhatsApp Web 的 linked device 方式，不是官方 WhatsApp Business Platform / Cloud API。</p><p>这意味着：</p><ul><li>不需要在 Meta for Developers 创建 App</li><li>不需要 WhatsApp Business Account（WABA）</li><li>不需要 Phone Number ID、WABA ID、Access Token</li><li>不需要配置 Webhook callback URL</li><li>不需要申请或审核 message template</li></ul><p>它的工作方式更接近“把 EchoFlow Code 作为一台已登录的 WhatsApp Web 设备挂到你的个人 WhatsApp 账号上”：</p><ol><li>桌面端用 Baileys 生成 WhatsApp Web 登录二维码</li><li>你用手机 WhatsApp 的 <code>Linked devices</code> 扫码</li><li>本机保存 WhatsApp Web auth state</li><li>adapter 监听这个账号收到的个人私聊消息</li><li>已授权用户发来的消息会被转成 EchoFlow Code session 输入</li><li>Claude 的回复再由这个 WhatsApp 账号发回同一个私聊</li></ol><p>因此，WhatsApp 这里没有 Telegram BotFather、飞书机器人、钉钉 Stream 机器人那种“后台创建 bot”的概念。对用户来说，对话对象就是你扫码绑定的那个 WhatsApp 账号本身。</p><p>如果后续要做面向客户服务、模板消息、官方 SLA、Webhook、规模化群发或合规商业账号接入，那是另一套官方 Cloud API 方案，需要单独实现，至少会涉及 Meta App、WABA、业务手机号、永久 access token、Webhook 和模板消息。参考官方资料：</p><ul><li><a href="https://faq.whatsapp.com/1317564962315842/" target="_blank" rel="noreferrer">WhatsApp Linked Devices 帮助</a></li><li><a href="https://developers.facebook.com/docs/whatsapp/cloud-api/overview" target="_blank" rel="noreferrer">Meta WhatsApp Cloud API Overview</a></li><li><a href="https://developers.facebook.com/docs/whatsapp/cloud-api/get-started" target="_blank" rel="noreferrer">Meta WhatsApp Cloud API Get Started</a></li></ul><h2 id="1-在桌面端扫码绑定" tabindex="-1">1. 在桌面端扫码绑定 <a class="header-anchor" href="#1-在桌面端扫码绑定" aria-label="Permalink to &quot;1. 在桌面端扫码绑定&quot;">​</a></h2><p>打开桌面端 <code>设置 -&gt; IM 接入 -&gt; WhatsApp</code>：</p><ol><li>点击「扫码绑定」</li><li>在手机 WhatsApp 打开 <code>Settings -&gt; Linked devices</code></li><li>扫描桌面端显示的二维码</li><li>等待页面提示绑定成功</li></ol><p>绑定成功后，桌面端会把 Baileys auth state 保存到本机，并重启 adapter sidecar。</p><p>默认 auth 目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.claude/whatsapp-auth/default</span></span></code></pre></div><p>配置记录写在：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;whatsapp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;accountJid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;15551234567@s.whatsapp.net&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;authDir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/.claude/whatsapp-auth/default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;allowedUsers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;pairedUsers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="2-生成配对码" tabindex="-1">2. 生成配对码 <a class="header-anchor" href="#2-生成配对码" aria-label="Permalink to &quot;2. 生成配对码&quot;">​</a></h2><p>扫码只绑定 WhatsApp Web 账号能力，不等于授权所有聊天用户。</p><p>在 <code>IM 接入</code> 页点击「生成配对码」，然后用需要授权的 WhatsApp 私聊给当前账号发送该配对码。配对成功后，这个 WhatsApp JID 会写入 <code>whatsapp.pairedUsers</code>。</p><p>也可以直接在 <code>Allowed Users</code> 里填写允许的 WhatsApp JID，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>15551234567@s.whatsapp.net</span></span></code></pre></div><h2 id="3-启动-adapter" tabindex="-1">3. 启动 adapter <a class="header-anchor" href="#3-启动-adapter" aria-label="Permalink to &quot;3. 启动 adapter&quot;">​</a></h2><p>发布版桌面端会自动拉起 adapter sidecar。本地开发或单独调试时：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adapters</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whatsapp</span></span></code></pre></div><h2 id="支持的命令" tabindex="-1">支持的命令 <a class="header-anchor" href="#支持的命令" aria-label="Permalink to &quot;支持的命令&quot;">​</a></h2><ul><li><code>/start</code> 或 <code>/help</code> — 显示帮助和可用命令</li><li><code>/projects</code> — 切换项目，重新显示最近项目列表</li><li><code>/status</code> — 查看当前会话的项目、模型和运行状态</li><li><code>/clear</code> — 清空当前会话上下文，保留项目绑定</li><li><code>/new [项目]</code> — 新建会话或切换项目</li><li><code>/stop</code> — 向当前 session 发送 <code>stop_generation</code></li></ul><h2 id="权限审批" tabindex="-1">权限审批 <a class="header-anchor" href="#权限审批" aria-label="Permalink to &quot;权限审批&quot;">​</a></h2><p>WhatsApp 没有使用按钮审批。收到权限请求后，按消息提示回复：</p><ul><li><code>1</code> 或 <code>/allow &lt;requestId&gt;</code> — 允许一次</li><li><code>2</code> 或 <code>/always &lt;requestId&gt;</code> — 永久允许</li><li><code>3</code> 或 <code>/deny &lt;requestId&gt;</code> — 拒绝</li></ul><h2 id="返回消息的表现" tabindex="-1">返回消息的表现 <a class="header-anchor" href="#返回消息的表现" aria-label="Permalink to &quot;返回消息的表现&quot;">​</a></h2><p>WhatsApp adapter 不依赖 WhatsApp message edit 做 token 级流式更新。它会：</p><ul><li>thinking 时发送一个简短状态提示</li><li>完成后把正文按约 4000 字分片发送</li><li>识别 Agent 输出里的 markdown 图片引用并作为图片消息发送</li></ul><h2 id="环境变量覆盖可选" tabindex="-1">环境变量覆盖（可选） <a class="header-anchor" href="#环境变量覆盖可选" aria-label="Permalink to &quot;环境变量覆盖（可选）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WHATSAPP_AUTH_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.claude/whatsapp-auth/default&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WHATSAPP_ACCOUNT_JID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;15551234567@s.whatsapp.net&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADAPTER_SERVER_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ws://127.0.0.1:3456&quot;</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="adapter-启动时报没有绑定账号" tabindex="-1">adapter 启动时报没有绑定账号 <a class="header-anchor" href="#adapter-启动时报没有绑定账号" aria-label="Permalink to &quot;adapter 启动时报没有绑定账号&quot;">​</a></h3><p>先在桌面端 WhatsApp 标签页扫码绑定。<code>bun run whatsapp</code> 不会单独弹出二维码。</p><h3 id="绑定后发消息提示未授权" tabindex="-1">绑定后发消息提示未授权 <a class="header-anchor" href="#绑定后发消息提示未授权" aria-label="Permalink to &quot;绑定后发消息提示未授权&quot;">​</a></h3><p>扫码绑定的是 WhatsApp Web 账号，不是用户授权。还需要在桌面端生成配对码，并用 WhatsApp 私聊发送给当前账号。</p><h3 id="whatsapp-提示已登出" tabindex="-1">WhatsApp 提示已登出 <a class="header-anchor" href="#whatsapp-提示已登出" aria-label="Permalink to &quot;WhatsApp 提示已登出&quot;">​</a></h3><p>在桌面端 WhatsApp 标签页解除绑定后重新扫码。解除绑定会删除本机 WhatsApp auth state。</p><h2 id="源码入口" tabindex="-1">源码入口 <a class="header-anchor" href="#源码入口" aria-label="Permalink to &quot;源码入口&quot;">​</a></h2><ul><li><code>adapters/whatsapp/index.ts</code></li><li><code>adapters/whatsapp/protocol.ts</code></li><li><code>adapters/whatsapp/session.ts</code></li><li><code>adapters/whatsapp/media.ts</code></li><li><code>adapters/common/pairing.ts</code></li><li><code>adapters/common/session-store.ts</code></li><li><code>adapters/common/ws-bridge.ts</code></li></ul>`,49)])])}const u=s(p,[["render",l]]);export{k as __pageData,u as default};
